"use client";

import { type HorizontalStepperProps, HorizontalStepperRoot } from "./horizontal-stepper";
import { HorizontalStepperStep, type HorizontalStepperStepProps } from "./horizontal-stepper-step";

/** Sibling primitive: compact horizontal step bar. */
const HorizontalStepper = Object.assign(HorizontalStepperRoot, {
  Step: HorizontalStepperStep,
});

export { HorizontalStepper, type HorizontalStepperProps };
export { HorizontalStepperStep, type HorizontalStepperStepProps };
export type { HorizontalStepStatus } from "./horizontal-stepper-context";
export type { HorizontalStepperVariant } from "./horizontal-stepper-variants";

"use client";

import {
  Children,
  type ComponentProps,
  isValidElement,
  type ReactNode,
  useCallback,
  useMemo,
  useRef,
  useState,
} from "react";
import { cn } from "@/lib/utils";
import { HorizontalStepperContext } from "./horizontal-stepper-context";
import { HorizontalStepperStep, type HorizontalStepperStepProps } from "./horizontal-stepper-step";
import {
  type HorizontalStepperVariant,
  horizontalStepperRootVariants,
} from "./horizontal-stepper-variants";

type NoInfer<T> = [T][T extends unknown ? 0 : never];

/** Props for horizontal stepper. */
export interface HorizontalStepperProps<TStep extends string = string>
  extends Omit<ComponentProps<"ol">, "children"> {
  /** Id of the active step. */
  value: NoInfer<TStep>;
  /** Visual variant. Drives the indicator glyph, connector treatment, and label typography. */
  variant?: HorizontalStepperVariant;
  /**
   * Forces the compact treatment: connectors drop out, only the active step keeps a visible label,
   * and that label is prefixed with "Step 3/6 ·". When false (default) the stepper switches to the
   * same treatment on its own once its container is narrower than 36rem.
   *
   * Compact has a second tier that stays on the container query either way: below 20rem the glyph
   * run is dropped too and only the "Step 3/6 · Label" text remains.
   */
  compact?: boolean;
  /** HorizontalStepper.Step children in the order they should render. */
  children: ReactNode;
}

const DOCUMENT_POSITION_FOLLOWING = 4;

// SSR/first-render seed before the registration effects run: descend through anything that is
// not a Step, since steps are commonly grouped inside plain wrapper elements.
function collectStepSeed(children: ReactNode): readonly string[] {
  const steps: string[] = [];

  Children.forEach(children, (child) => {
    if (!isValidElement<{ children?: ReactNode }>(child)) return;

    if (child.type === HorizontalStepperStep) {
      steps.push((child.props as HorizontalStepperStepProps).value);
      return;
    }

    steps.push(...collectStepSeed(child.props.children));
  });

  return steps;
}

function isSameRun(a: readonly string[], b: readonly string[]): boolean {
  return a.length === b.length && a.every((step, index) => step === b[index]);
}

/**
 * Seed/live step run. The static child scan only sees elements the caller literally created, so
 * mounted steps take over as the authority once they register and a run assembled inside a
 * consumer component still reports its real order and length.
 */
function useStepRun(seed: readonly string[]) {
  const [mounted, setMounted] = useState<readonly string[]>([]);
  const mountedStepsRef = useRef(new Map<HTMLElement, string>());

  // Document order is read here rather than inside the updater: setState updaters must stay
  // pure under StrictMode replay.
  const commit = useCallback(() => {
    const next = [...mountedStepsRef.current]
      .sort(([a], [b]) => (a.compareDocumentPosition(b) & DOCUMENT_POSITION_FOLLOWING ? -1 : 1))
      .map(([, step]) => step);
    setMounted((current) => (isSameRun(current, next) ? current : next));
  }, []);

  const registerStep = useCallback(
    (step: string, element: HTMLElement) => {
      mountedStepsRef.current.set(element, step);
      commit();
      return () => {
        mountedStepsRef.current.delete(element);
        commit();
      };
    },
    [commit],
  );

  return { steps: mounted.length > 0 ? mounted : seed, registerStep };
}

function assertActiveStep(steps: readonly string[], value: string): void {
  // An empty run means the scan found nothing and no step has registered yet, so there is
  // nothing to judge the active value against until the mounted steps arrive.
  if (steps.length === 0 || steps.includes(value)) return;
  throw new Error(
    `HorizontalStepper: value "${value}" is not present in rendered step children [${steps.join(", ")}]`,
  );
}

/** Sibling primitive: compact horizontal step bar. */
export function HorizontalStepperRoot<TStep extends string>({
  value,
  variant = "ascii",
  compact = false,
  children,
  className,
  "aria-label": ariaLabel,
  ...props
}: HorizontalStepperProps<TStep>) {
  const seed = useMemo(() => collectStepSeed(children), [children]);
  const { steps, registerStep } = useStepRun(seed);
  assertActiveStep(steps, value);

  const contextValue = useMemo(
    () => ({ value, steps, variant, compact, registerStep }),
    [value, steps, variant, compact, registerStep],
  );

  return (
    <HorizontalStepperContext value={contextValue}>
      {/* biome-ignore lint/a11y/useSemanticElements: this already is an <ol>; the explicit role="list" below restores list semantics that Tailwind preflight strips, and Biome should not suggest swapping the element. */}
      <ol
        {...props}
        // biome-ignore lint/a11y/noRedundantRoles: Tailwind preflight sets list-style:none on <ol>, which drops list semantics in Safari/VoiceOver; role="list" restores them.
        role="list"
        aria-label={ariaLabel || "Progress"}
        data-slot="horizontal-stepper"
        data-variant={variant}
        className={cn(horizontalStepperRootVariants({ variant }), className)}
      >
        {children}
      </ol>
    </HorizontalStepperContext>
  );
}

"use client";

import { createContext, useContext } from "react";
import type { HorizontalStepStatus, StepStatus } from "@/lib/step-status";
import type { HorizontalStepperVariant } from "./horizontal-stepper-variants";

export type { HorizontalStepStatus, StepStatus };

/** Context value shared by stepper. */
interface StepperContextValue<TStep extends string = string> {
  /** Id of the active step. */
  value: TStep;
  /**
   * Ordered step ids. Used to compute status (completed/active/pending) for each step relative
   * to value.
   */
  steps: readonly TStep[];
  /** Visual variant. Controls the indicator glyph and connector treatment across every step. */
  variant: HorizontalStepperVariant;
  /** True when the compact treatment is forced instead of left to the container query. */
  compact: boolean;
  /**
   * Announces a mounted step to the root and returns its cleanup. The root's static child scan
   * cannot see steps a consumer component renders, so the mounted elements are what fix the run's
   * real order and length.
   */
  registerStep: (step: string, element: HTMLElement) => () => void;
}

export const HorizontalStepperContext = createContext<StepperContextValue | undefined>(undefined);

export function useHorizontalStepperContext<
  TStep extends string = string,
>(): StepperContextValue<TStep> {
  const ctx = useContext(HorizontalStepperContext);
  if (ctx === undefined) {
    throw new Error("HorizontalStepperStep must be used within a HorizontalStepper");
  }
  return ctx as StepperContextValue<TStep>;
}

export function useStepInfo<TStep extends string = string>(
  value: TStep,
): {
  status: HorizontalStepStatus;
  index: number;
  total: number;
  /** Index of the active step, so a step can tell how far it sits from the window centre. */
  activeIndex: number;
} {
  const { value: currentValue, steps } = useHorizontalStepperContext<TStep>();
  const stepIndex = steps.indexOf(value);
  const currentIndex = steps.indexOf(currentValue);
  const total = steps.length;
  const info = { index: stepIndex, total, activeIndex: currentIndex };

  if (stepIndex === currentIndex) return { status: "active", ...info };
  if (stepIndex < currentIndex) return { status: "completed", ...info };
  return { status: "pending", ...info };
}

"use client";

import { type ReactNode, useLayoutEffect, useRef } from "react";
import { renderSelectableGlyph } from "@/lib/selectable-glyph";
import { cn } from "@/lib/utils";
import {
  type HorizontalStepStatus,
  useHorizontalStepperContext,
  useStepInfo,
} from "./horizontal-stepper-context";
import {
  HORIZONTAL_STEP_INDICATOR_GLYPHS,
  type HorizontalStepperVariant,
  horizontalStepperActiveOnlyCollapseClass,
  horizontalStepperBreadcrumbSeparatorClass,
  horizontalStepperCompletedConnectorClass,
  horizontalStepperConnectorClass,
  horizontalStepperConnectorDisplayClass,
  horizontalStepperConnectorItemClass,
  horizontalStepperCounterClass,
  horizontalStepperCounterVisibilityClass,
  horizontalStepperElisionClass,
  horizontalStepperGlyphVariants,
  horizontalStepperLabelVariants,
  horizontalStepperStepVariants,
  horizontalStepperWindowClasses,
} from "./horizontal-stepper-variants";

const SR_LABEL: Record<HorizontalStepStatus, string> = {
  completed: "Completed: ",
  active: "Current: ",
  pending: "Upcoming: ",
};

/** Props for horizontal stepper step. */
export interface HorizontalStepperStepProps {
  /** Step id matched against the parent value to derive status. */
  value: string;
  /** Step label. */
  children: ReactNode;
  /** Additional class names merged onto the rendered element. */
  className?: string;
}

/** Single horizontal step (derives status from parent value) */
export function HorizontalStepperStep({ value, children, className }: HorizontalStepperStepProps) {
  const { variant, compact, registerStep } = useHorizontalStepperContext();
  const { status, index, total, activeIndex } = useStepInfo(value);
  const itemRef = useRef<HTMLLIElement>(null);

  useLayoutEffect(() => {
    const item = itemRef.current;
    if (!item) return;
    return registerStep(value, item);
  }, [registerStep, value]);

  const showConnectorBefore = index > 0;
  const isActive = status === "active";
  const distance = index - activeIndex;
  const windowClasses = horizontalStepperWindowClasses(variant, total, compact);
  // The markers ride the two steps flanking the active one, so they read in run order
  // (`+2 [x] [~] [ ] +1`) while the list still holds exactly one <li> per step.
  const hiddenBefore = distance === -1 ? activeIndex - 1 : 0;
  const hiddenAfter = distance === 1 ? total - activeIndex - 2 : 0;

  const glyph = renderGlyph(variant, status);
  const connector = renderConnector(variant, status === "completed");

  return (
    <>
      {showConnectorBefore && connector !== null && (
        <li
          role="presentation"
          aria-hidden="true"
          className={cn(
            horizontalStepperConnectorItemClass,
            horizontalStepperConnectorDisplayClass(compact),
          )}
        >
          {connector}
        </li>
      )}
      <li
        ref={itemRef}
        aria-current={isActive ? "step" : undefined}
        data-status={status}
        className={cn(
          horizontalStepperStepVariants({ variant }),
          // Both compact branches are written out in full here and on the label below.
          // Tailwind scans the built JS for complete class strings (the @source globs in
          // libs/ui/styles/sources.css), so a class assembled by interpolating
          // `@max-xl/horizontal-stepper:` onto a variable ships only the bare prefix and
          // no utility is ever emitted. The trailing space keeps the next step's `[ ]` off
          // the last word of the active label once the connectors are gone.
          isActive && (compact ? "pe-1.5" : "@max-xl/horizontal-stepper:pe-1.5"),
          !isActive && horizontalStepperActiveOnlyCollapseClass,
          Math.abs(distance) > 1 && windowClasses.window,
          className,
        )}
      >
        {hiddenBefore > 0 && (
          <span
            aria-hidden="true"
            className={cn(horizontalStepperElisionClass, windowClasses.elision)}
          >
            +{hiddenBefore}
          </span>
        )}
        {glyph !== null && (
          <span className={horizontalStepperGlyphVariants({ variant, status })}>
            <span className="sr-only">{SR_LABEL[status]}</span>
            {glyph}
          </span>
        )}
        <span
          className={cn(
            horizontalStepperLabelVariants({ variant, status }),
            // `sr-only` rather than `hidden`: the collapsed label leaves the layout but stays
            // in the accessibility tree, so every step is still announced.
            !isActive && (compact ? "sr-only" : "@max-xl/horizontal-stepper:sr-only"),
          )}
        >
          {glyph === null && <span className="sr-only">{SR_LABEL[status]}</span>}
          {isActive && (
            // Position is already conveyed by the list and aria-current; this prefix is the
            // visual stand-in for the labels the compact treatment hides.
            <span
              aria-hidden="true"
              className={cn(
                horizontalStepperCounterClass,
                horizontalStepperCounterVisibilityClass(compact),
              )}
            >
              Step {index + 1}/{total} ·
            </span>
          )}
          {children}
        </span>
        {hiddenAfter > 0 && (
          <span
            aria-hidden="true"
            className={cn(horizontalStepperElisionClass, windowClasses.elision)}
          >
            +{hiddenAfter}
          </span>
        )}
      </li>
    </>
  );
}

function renderConnector(variant: HorizontalStepperVariant, isCompleted: boolean): ReactNode {
  if (variant === "ascii") {
    return (
      <span
        className={cn(
          horizontalStepperConnectorClass,
          isCompleted && horizontalStepperCompletedConnectorClass,
        )}
      >
        ───
      </span>
    );
  }
  if (variant === "breadcrumb") {
    return <span className={horizontalStepperBreadcrumbSeparatorClass}>/</span>;
  }
  // Numbered draws its connector as a ::before segment on the step itself.
  return null;
}

function renderGlyph(variant: HorizontalStepperVariant, status: HorizontalStepStatus): ReactNode {
  if (variant === "numbered") {
    if (status === "completed") return "✓";
    return <span data-counter aria-hidden="true" />;
  }
  if (variant === "breadcrumb" && status === "pending") return null;
  // Same glyph grammar as the form controls: dim brackets, bold mark. The breadcrumb `✓` and `›`
  // are unbracketed and pass through untouched.
  return renderSelectableGlyph(HORIZONTAL_STEP_INDICATOR_GLYPHS[variant][status]);
}
